import { describe, expect, it } from 'vitest'
import { configureCodeBlockCollapsing, decorateCodeBlock, toggleCodeBlockCollapse } from '../../lib/markdown/enhance'
import { renderMarkdown } from '../../lib/markdown/renderer'
import { capturePreviewInteractionState, restorePreviewInteractionState } from './preview-state'
import { selectMarkdownTab } from './markdown-tabs'

describe('preview interaction state', () => {
  it('namespaces interactive IDs for separate preview instances', () => {
    const source = `:::: tabs\n::: tab-item One\nFirst[^note]\n:::\n::::\n\n[^note]: Footnote`
    const first = document.createElement('div')
    const second = document.createElement('div')
    first.innerHTML = renderMarkdown(source).html
    second.innerHTML = renderMarkdown(source).html

    const firstIds = new Set([...first.querySelectorAll<HTMLElement>('[id]')].map((node) => node.id))
    const secondIds = [...second.querySelectorAll<HTMLElement>('[id]')].map((node) => node.id)
    expect(secondIds.every((id) => !firstIds.has(id))).toBe(true)

    for (const root of [first, second]) {
      root.querySelectorAll<HTMLButtonElement>('[aria-controls]').forEach((button) => {
        expect(root.querySelector(`#${CSS.escape(button.getAttribute('aria-controls')!)}`)).not.toBeNull()
      })
      root.querySelectorAll<HTMLAnchorElement>('a[href^="#"]').forEach((anchor) => {
        expect(root.querySelector(anchor.getAttribute('href')!)).not.toBeNull()
      })
    }
  })

  it('renders stable source-line keys for interactive Markdown blocks', () => {
    const rendered = renderMarkdown(`::: details Open\nBody\n:::\n\n:::: tabs\n::: tab-item One\nFirst\n:::\n::: tab-item Two\nSecond\n:::\n::::`)
    const root = document.createElement('div')
    root.innerHTML = rendered.html

    expect(root.querySelector('.markdown-details')?.hasAttribute('data-line')).toBe(true)
    expect(root.querySelector('[data-tabs]')?.hasAttribute('data-line')).toBe(true)
  })

  it('restores expanded code, details, and selected tabs after a preview rebuild', () => {
    const original = previewFixture()
    prepareCodeBlock(original)
    toggleCodeBlockCollapse(original.querySelector<HTMLButtonElement>('[data-code-collapse]')!)
    original.querySelector<HTMLDetailsElement>('details')!.open = false
    selectMarkdownTab(original.querySelectorAll<HTMLButtonElement>('[data-tab-button]')[1]!)
    const state = capturePreviewInteractionState(original)

    const rebuilt = previewFixture()
    prepareCodeBlock(rebuilt)
    restorePreviewInteractionState(rebuilt, state)

    expect(rebuilt.querySelector('.code-block')!.classList.contains('is-code-expanded')).toBe(true)
    expect(rebuilt.querySelector<HTMLDetailsElement>('details')!.open).toBe(false)
    expect(rebuilt.querySelectorAll<HTMLButtonElement>('[data-tab-button]')[1]!.getAttribute('aria-selected')).toBe('true')
    expect(rebuilt.querySelectorAll<HTMLElement>('[data-tab-panel]')[0]!.hidden).toBe(true)
  })
})

function previewFixture(): HTMLDivElement {
  const root = document.createElement('div')
  root.innerHTML = `
    <div class="code-block" data-line="4"><div class="code-block-head"><button data-copy>Copy</button></div><pre><code>1\n2\n3\n4\n5\n6\n7\n8\n9</code></pre></div>
    <details data-line="20" open><summary>More</summary><p>Body</p></details>
    <div data-tabs data-line="30"><div role="tablist"><button data-tab-button="0" aria-selected="true">A</button><button data-tab-button="1" aria-selected="false">B</button></div><section data-tab-panel="0"></section><section data-tab-panel="1" hidden></section></div>
  `
  return root
}

function prepareCodeBlock(root: HTMLElement): void {
  decorateCodeBlock(root.querySelector<HTMLElement>('.code-block')!)
  configureCodeBlockCollapsing(root, 8)
}

import { describe, expect, it } from 'vitest';
import { renderMarkdownBlocks } from '../lib/markdown/renderer';
import { mergeSettings } from '@shared/constants';

describe('live preview Markdown compatibility', () => {
    it('migrates old layouts while preserving split and unrelated settings', () => {
        for (const layout of ['edit', 'live']) {
            const settings = mergeSettings({ preview: { layout, math: false }, editor: { tabSize: 4 } });
            expect(settings.preview.layout).toBe('live');
            expect(settings.preview.math).toBe(false);
            expect(settings.editor.tabSize).toBe(4);
        }
        for (const layout of ['split', 'preview']) expect(mergeSettings({ preview: { layout } }).preview.layout).toBe(layout);
    });
    it('retains document-wide references and source lines across nested blocks', () => {
        const source = '# Heading\n\n[Reference][ref]\n\n- [ ] one\n  - [x] two\n\n| A | B |\n| - | - |\n| C | D |\n\n[ref]: https://example.com';
        const { blocks, headings } = renderMarkdownBlocks(source);
        expect(blocks.map((block) => [block.startLine, block.endLine])).toEqual([[0, 1], [2, 3], [4, 7], [7, 10]]);
        expect(blocks[1]!.html).toContain('href="https://example.com"');
        expect(blocks[2]!.html).toContain('data-task-line="4"');
        expect(blocks[2]!.html).toContain('data-task-line="5"');
        expect(blocks[3]!.html).toContain('<table');
        expect(headings[0]?.line).toBe(0);
    });
    it('keeps sanitization and comments source mapping intact', () => {
        const { blocks } = renderMarkdownBlocks('%% SECRET_COMMENT %%\n\n# Visible\n\n<img src="x" onerror="alert(1)">\n\n<script>alert(1)</script>');
        const html = blocks.map((block) => block.html).join('');
        expect(html).not.toContain('onerror');
        expect(html).not.toContain('<script');
        expect(html).not.toContain('SECRET_COMMENT');
        expect(blocks.find((block) => block.html.includes('Visible'))?.startLine).toBe(2);
    });
});

import { describe, expect, it } from 'vitest';
import {
    canonicalizeMcpRequestId,
    getMcpRequestContext,
    runWithMcpRequestContext,
} from './request-context.js';

describe('canonicalizeMcpRequestId', () => {
    it('namespaces by type so string and number ids never collide', () => {
        expect(canonicalizeMcpRequestId('1')).toBe('str:1');
        expect(canonicalizeMcpRequestId(1)).toBe('num:1');
        expect(canonicalizeMcpRequestId('1')).not.toBe(canonicalizeMcpRequestId(1));
    });

    it('keeps distinct ids distinct even with colliding text', () => {
        expect(canonicalizeMcpRequestId('num:5')).toBe('str:num:5');
        expect(canonicalizeMcpRequestId(5)).toBe('num:5');
        expect(canonicalizeMcpRequestId('num:5')).not.toBe(canonicalizeMcpRequestId(5));
    });

    it('is stable for the same input', () => {
        expect(canonicalizeMcpRequestId(42)).toBe(canonicalizeMcpRequestId(42));
        expect(canonicalizeMcpRequestId('abc')).toBe(canonicalizeMcpRequestId('abc'));
    });
});

describe('McpRequestContext async-local storage', () => {
    it('is empty outside a request context', () => {
        expect(getMcpRequestContext()).toBeUndefined();
    });

    it('is readable inside runWithMcpRequestContext and cleared after', () => {
        const seen: Array<string | undefined> = [];
        runWithMcpRequestContext({ requestId: 'mcp:7', signal: undefined }, () => {
            seen.push(getMcpRequestContext()?.requestId);
        });
        seen.push(getMcpRequestContext()?.requestId);
        expect(seen).toEqual(['mcp:7', undefined]);
    });

    it('propagates through async boundaries', async () => {
        const seen = await runWithMcpRequestContext({ requestId: 'mcp:9', signal: undefined }, async () => {
            await Promise.resolve();
            return getMcpRequestContext()?.requestId;
        });
        expect(seen).toBe('mcp:9');
    });
});

import { describe, expect, it } from 'vitest';
import {
  InMemoryRevisionProvider,
  asResourceRevision,
} from '../server/mcp-primitives/resource-revision.js';
import { ResourceError } from './resource-errors.js';
import {
  EditorStateResources,
  type EditorStateSource,
  type SelectionEntry,
} from './editor-state-resources.js';

const LIVE_REVISIONS = { selection: 2, level: 3, assetRegistry: 4, package: 5 } as const;

function source(overrides: Partial<EditorStateSource> = {}): EditorStateSource {
  return {
    isAvailable: async () => true,
    engineVersion: async () => '5.7.4',
    pieActive: async () => false,
    currentLevel: async () => ({ name: 'Main', path: '/Game/Maps/Main' }),
    selectedActors: async () => [{ name: 'Cube', path: '/Game/Cube' }],
    liveRevisions: async () => LIVE_REVISIONS,
    ...overrides,
  };
}

function provider(): InMemoryRevisionProvider {
  const instance = new InMemoryRevisionProvider();
  instance.set('ue://project', asResourceRevision(2));
  instance.set('ue://pie', asResourceRevision(3));
  instance.set('ue://selection', asResourceRevision(4));
  return instance;
}

describe('editor-state-resources', () => {
  it('reads a redacted, connected project with its revision', async () => {
    // Given
    const resources = new EditorStateResources(source(), provider(), 'MyGame');

    // When
    const project = await resources.readProject();

    // Then
    expect(project.revision).toBe(2);
    expect(project.data).toEqual({
      projectName: 'MyGame',
      engineVersion: '5.7.4',
      contentRoot: '/Game',
      connected: true,
    });
  });

  it('reads a project offline without an engine version and never throws', async () => {
    // Given
    const resources = new EditorStateResources(source({ isAvailable: async () => false }), provider(), null);

    // When
    const project = await resources.readProject();

    // Then
    expect(project.data.connected).toBe(false);
    expect(project.data.engineVersion).toBeNull();
    expect(project.data.projectName).toBeNull();
  });

  it('reads editor state tagged with the PIE revision', async () => {
    // Given
    const resources = new EditorStateResources(source({ pieActive: async () => true }), provider(), 'MyGame');

    // When
    const editor = await resources.readEditor();

    // Then
    expect(editor.revision).toBe(3);
    expect(editor.data.pieActive).toBe(true);
    expect(editor.data.currentLevel).toEqual({ name: 'Main', path: '/Game/Maps/Main' });
  });

  it('throws UNAVAILABLE for editor and selection when disconnected', async () => {
    // Given
    const resources = new EditorStateResources(source({ isAvailable: async () => false }), provider(), 'MyGame');

    // When / Then
    await expect(resources.readEditor()).rejects.toBeInstanceOf(ResourceError);
    await expect(resources.readSelection()).rejects.toMatchObject({ code: 'RESOURCE_UNAVAILABLE' });
  });

  it('caps the selection and reports truncation', async () => {
    // Given
    const many: SelectionEntry[] = Array.from({ length: 250 }, (_unused, index) => ({
      name: `Actor_${index}`,
      path: `/Game/Actor_${index}`,
    }));
    const resources = new EditorStateResources(source({ selectedActors: async () => many }), provider(), 'MyGame');

    // When
    const selection = await resources.readSelection();

    // Then
    expect(selection.revision).toBe(4);
    expect(selection.data.count).toBe(200);
    expect(selection.data.totalCount).toBe(250);
    expect(selection.data.truncated).toBe(true);
    expect(selection.data.actors).toHaveLength(200);
  });

  it('reads the exact live revision snapshot and uses its maximum as the resource revision', async () => {
    const resources = new EditorStateResources(source(), provider(), 'MyGame');

    const revisions = await resources.readStateRevisions();

    expect(revisions.revision).toBe(5);
    expect(revisions.data).toEqual(LIVE_REVISIONS);
  });
});

//! The oracle net for tool input schemas.
//!
//! `cc_input_schemas.json` is generated by running the real CC tool modules
//! under `bun` and projecting each `tool.inputSchema` through zod v4's
//! `toJSONSchema` — the same call `utils/zodToJsonSchema.ts` wraps and
//! `utils/api.ts:160` ships to the API as `input_schema`. Regenerate with:
//!
//! ```text
//! cd ../rebuild && bun ../CometixCode/scripts/dump_cc_tool_schemas.mjs \
//!   > ../CometixCode/src/tools/cc_input_schemas.json
//! ```
//!
//! A tool listed in [`MIGRATED`] has had its hand-written JSON literal replaced
//! by the carrier projection, and must reproduce CC's output exactly. Tools not
//! yet listed still carry a literal; adding one here is what "migrated" means.
//!
//! [`OUTSIDE_THE_NET`] records the oracle entries no `fn() -> Tool` can serve,
